function dominantIndex(nums: number[]): number {
  let idx = 0;
  for (let i = 1; i < nums.length; i++) if (nums[i] > nums[idx]) idx = i;
  for (let i = 0; i < nums.length; i++) {
    if (i !== idx && nums[idx] < 2 * nums[i]) return -1;
  }
  return idx;
}

