function dominantIndex(nums: number[]): number {
  let best = -1, second = -1, idx = 0;
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] > best) {
      second = best;
      best = nums[i];
      idx = i;
    } else if (nums[i] > second) {
      second = nums[i];
    }
  }
  return best >= 2 * second ? idx : -1;
}

